/* ============================================================
   relay.js - the matchmaking relay as a Durable Object.

   Why a Durable Object: matchmaking needs one place that sees every
   waiting player. Ordinary serverless isolates each hold their own
   memory, so two people pressing PLAY could land in different copies
   and never find each other. A DO is a single addressable instance -
   every socket for this game routes to the same one.

   The wire protocol is byte-identical to server/server.js, so the game
   client does not know or care which one it is talking to. What goes
   away is the hand-rolled RFC 6455 implementation: the platform gives
   us real WebSockets, so there are no frames to encode by hand.
   ============================================================ */

const MAX_CLIENTS = 400;
const MSG_PER_SEC = 60;
const CODE_CHARS = 'ABCDEFGHJKMNPQRSTUVWXYZ23456789';   // no O/0/I/1
const ROOM_TTL_MS = 15 * 60 * 1000;
const BOARD_KEEP = 200;
const BOARD_MAX_SCORE = 2000;
const SUBMITS_PER_HOUR = 40;

const rnd = (n) => crypto.getRandomValues(new Uint8Array(n));
const rndInt = (max) => rnd(1)[0] % max;

function sanitizeProfile(p) {
  const o = p && typeof p === 'object' ? p : {};
  const name = String(o.name ?? 'PLAYER').slice(0, 12).replace(/[�-]/g, '') || 'PLAYER';
  const lo = o.loadout && typeof o.loadout === 'object' ? o.loadout : {};
  const pick = (v) => (typeof v === 'string' ? v.slice(0, 24) : undefined);
  return {
    id: String(o.id ?? '').slice(0, 40),
    name,
    level: Math.max(1, Math.min(999, Number(o.level) || 1)),
    loadout: {
      skin: pick(lo.skin), hat: pick(lo.hat), face: pick(lo.face),
      trail: pick(lo.trail), emote: pick(lo.emote),
      victory: pick(lo.victory), plate: pick(lo.plate),
    },
  };
}

export class Relay {
  constructor(ctx, env) {
    this.ctx = ctx;
    this.env = env;
    this.clients = new Map();      // id -> client
    this.queue = [];               // ids waiting for a public match
    this.privateRooms = new Map(); // code -> { hostId, created }
    this.nextId = 1;

    this.sql = ctx.storage.sql;
    this.sql.exec(`CREATE TABLE IF NOT EXISTS board (
      id TEXT PRIMARY KEY, name TEXT NOT NULL, score INTEGER NOT NULL,
      hold REAL NOT NULL DEFAULT 0, wins INTEGER NOT NULL DEFAULT 0,
      updated INTEGER NOT NULL
    )`);
    this.sql.exec(`CREATE TABLE IF NOT EXISTS submits (
      ip TEXT NOT NULL, at INTEGER NOT NULL
    )`);
  }

  async fetch(request) {
    const url = new URL(request.url);

    if (url.pathname === '/ws') return this.openSocket(request);
    if (url.pathname === '/api/top') return this.topScores(url);
    if (url.pathname === '/api/score') return this.submitScore(request);
    if (url.pathname === '/health') {
      return json({
        ok: true,
        clients: this.clients.size,
        queued: this.queue.length,
        privateRooms: this.privateRooms.size,
        boardSize: this.countBoard(),
      });
    }
    return new Response('not found', { status: 404 });
  }

  /* ---------------- websocket ---------------- */
  openSocket(request) {
    if (request.headers.get('Upgrade') !== 'websocket') {
      return new Response('expected websocket', { status: 426 });
    }
    if (this.clients.size >= MAX_CLIENTS) {
      return new Response('server full', { status: 503 });
    }

    const pair = new WebSocketPair();
    const [client, server] = Object.values(pair);
    server.accept();

    const id = this.nextId++;
    const c = {
      id, ws: server, room: null, peer: null, queued: false,
      profile: sanitizeProfile(null), msgs: 0, window: Date.now(),
    };
    this.clients.set(id, c);
    this.send(c, { t: 'welcome', id, v: 1 });

    server.addEventListener('message', (ev) => {
      try { this.onMessage(c, ev.data); } catch (_) { /* never kill the socket */ }
    });
    const bye = () => this.drop(c);
    server.addEventListener('close', bye);
    server.addEventListener('error', bye);

    return new Response(null, { status: 101, webSocket: client });
  }

  send(c, obj) {
    if (!c) return;
    try { c.ws.send(JSON.stringify(obj)); } catch (_) { /* gone */ }
  }

  onMessage(c, raw) {
    const now = Date.now();
    if (now - c.window > 1000) { c.window = now; c.msgs = 0; }
    if (++c.msgs > MSG_PER_SEC) return;
    if (typeof raw !== 'string' || raw.length > 64 * 1024) return;

    let m;
    try { m = JSON.parse(raw); } catch (_) { return; }
    if (!m || typeof m.t !== 'string') return;

    switch (m.t) {
      case 'hello':
        c.profile = sanitizeProfile(m.profile);
        break;

      case 'queue':
        if (c.room) this.leaveRoom(c);
        if (!c.queued) { c.queued = true; this.queue.push(c.id); }
        this.send(c, { t: 'queued', n: this.queue.indexOf(c.id) + 1 });
        this.tryMatch();
        break;

      case 'cancel':
        c.queued = false;
        this.dequeue(c.id);
        this.dropPrivateRoom(c.id);
        break;

      case 'mkroom': {
        if (c.room) this.leaveRoom(c);
        this.dequeue(c.id); c.queued = false;
        this.dropPrivateRoom(c.id);
        this.expireRooms();
        const code = this.makeCode();
        if (!code) { this.send(c, { t: 'err', m: 'could not create a room' }); break; }
        this.privateRooms.set(code, { hostId: c.id, created: Date.now() });
        this.send(c, { t: 'room', code });
        break;
      }

      case 'joinroom': {
        const code = String(m.code || '').toUpperCase().replace(/[^A-Z0-9]/g, '').slice(0, 4);
        const room = this.privateRooms.get(code);
        if (!room) { this.send(c, { t: 'err', m: 'No room with that code.', code: 'noroom' }); break; }
        const host = this.clients.get(room.hostId);
        if (!host) {
          this.privateRooms.delete(code);
          this.send(c, { t: 'err', m: 'That room has closed.', code: 'noroom' });
          break;
        }
        if (host.id === c.id) { this.send(c, { t: 'err', m: 'That is your own code.', code: 'self' }); break; }
        this.privateRooms.delete(code);
        if (c.room) this.leaveRoom(c);
        this.dequeue(c.id); c.queued = false;
        this.pair(host, c);
        break;
      }

      case 'rly': {
        const peer = this.clients.get(c.peer);
        if (peer && c.room && peer.room === c.room) this.send(peer, { t: 'rly', d: m.d });
        break;
      }

      case 'ping':
        this.send(c, { t: 'pong', s: m.s });
        break;

      default: break;
    }
  }

  /* ---------------- matchmaking ---------------- */
  dequeue(id) {
    const i = this.queue.indexOf(id);
    if (i >= 0) this.queue.splice(i, 1);
  }

  dropPrivateRoom(hostId) {
    for (const [code, r] of this.privateRooms) {
      if (r.hostId === hostId) this.privateRooms.delete(code);
    }
  }

  expireRooms() {
    const now = Date.now();
    for (const [code, r] of this.privateRooms) {
      if (now - r.created > ROOM_TTL_MS) this.privateRooms.delete(code);
    }
  }

  makeCode() {
    for (let attempt = 0; attempt < 50; attempt++) {
      let c = '';
      for (let i = 0; i < 4; i++) c += CODE_CHARS[rndInt(CODE_CHARS.length)];
      if (!this.privateRooms.has(c)) return c;
    }
    return null;
  }

  pair(a, b) {
    const roomId = [...rnd(6)].map((x) => x.toString(16).padStart(2, '0')).join('');
    const r = rnd(4);
    const seed = (((r[0] << 24) | (r[1] << 16) | (r[2] << 8) | r[3]) >>> 0) || 1;
    const aHost = rnd(1)[0] < 128;
    a.room = roomId; a.peer = b.id; a.queued = false;
    b.room = roomId; b.peer = a.id; b.queued = false;
    this.send(a, { t: 'match', room: roomId, seed, idx: aHost ? 0 : 1, host: aHost, opp: b.profile, v: 1 });
    this.send(b, { t: 'match', room: roomId, seed, idx: aHost ? 1 : 0, host: !aHost, opp: a.profile, v: 1 });
  }

  tryMatch() {
    while (this.queue.length >= 2) {
      const a = this.clients.get(this.queue.shift());
      const bId = this.queue.shift();
      const b = this.clients.get(bId);
      if (!a) { if (b) this.queue.unshift(bId); continue; }
      if (!b) { this.queue.unshift(a.id); continue; }
      this.pair(a, b);
    }
    this.queue.forEach((id, i) => this.send(this.clients.get(id), { t: 'queued', n: i + 1 }));
  }

  leaveRoom(c, notify = true) {
    if (!c.room) return;
    const peer = this.clients.get(c.peer);
    if (peer && peer.room === c.room) {
      peer.room = null; peer.peer = null;
      if (notify) this.send(peer, { t: 'peerLeft' });
    }
    c.room = null; c.peer = null;
  }

  drop(c) {
    if (!this.clients.has(c.id)) return;
    this.leaveRoom(c);
    this.dequeue(c.id);
    this.dropPrivateRoom(c.id);
    this.clients.delete(c.id);
    this.tryMatch();
  }

  /* ---------------- leaderboard (SQLite in the DO) ---------------- */
  countBoard() {
    return [...this.sql.exec('SELECT COUNT(*) AS n FROM board')][0]?.n ?? 0;
  }

  topScores(url) {
    const limit = Math.max(1, Math.min(50, Number(url.searchParams.get('limit')) || 25));
    const rows = [...this.sql.exec(
      'SELECT id, name, score, hold, wins FROM board ORDER BY score DESC LIMIT ?', limit,
    )];
    return json({ rows });
  }

  async submitScore(request) {
    const ip = request.headers.get('CF-Connecting-IP') || 'unknown';
    const hourAgo = Date.now() - 3600_000;
    this.sql.exec('DELETE FROM submits WHERE at < ?', hourAgo);
    const recent = [...this.sql.exec('SELECT COUNT(*) AS n FROM submits WHERE ip = ?', ip)][0]?.n ?? 0;
    if (recent >= SUBMITS_PER_HOUR) return json({ ok: false, why: 'slow down' }, 429);

    let body;
    try { body = await request.json(); } catch (_) { return json({ ok: false, why: 'bad json' }, 400); }

    const score = Number(body?.score);
    if (!Number.isFinite(score) || score < 0 || score > BOARD_MAX_SCORE) {
      return json({ ok: false, why: 'bad score' }, 400);
    }
    const id = String(body?.id ?? '').slice(0, 40);
    if (!id) return json({ ok: false, why: 'no id' }, 400);
    const name = (String(body?.name ?? 'PLAYER').slice(0, 12).replace(/[�-]/g, '')) || 'PLAYER';
    const hold = Math.max(0, Math.min(600, Number(body?.hold) || 0));
    const won = body?.won ? 1 : 0;

    this.sql.exec('INSERT INTO submits (ip, at) VALUES (?, ?)', ip, Date.now());

    const prev = [...this.sql.exec('SELECT score, wins FROM board WHERE id = ?', id)][0];
    const best = Math.max(score, prev?.score ?? 0);
    const wins = (prev?.wins ?? 0) + won;
    this.sql.exec(
      `INSERT INTO board (id, name, score, hold, wins, updated) VALUES (?, ?, ?, ?, ?, ?)
       ON CONFLICT(id) DO UPDATE SET name = excluded.name, score = excluded.score,
         hold = MAX(board.hold, excluded.hold), wins = excluded.wins, updated = excluded.updated`,
      id, name, best, hold, wins, Date.now(),
    );

    // keep the table bounded
    this.sql.exec(
      `DELETE FROM board WHERE id NOT IN (SELECT id FROM board ORDER BY score DESC LIMIT ?)`,
      BOARD_KEEP,
    );

    const rank = ([...this.sql.exec('SELECT COUNT(*) AS n FROM board WHERE score > ?', best)][0]?.n ?? 0) + 1;
    return json({ ok: true, rank, best });
  }
}

export function json(obj, status = 200) {
  return new Response(JSON.stringify(obj), {
    status,
    headers: {
      'content-type': 'application/json',
      'cache-control': 'no-store',
      // the game may be served from Pages or anywhere else
      'access-control-allow-origin': '*',
      vary: 'origin',
    },
  });
}
